// Browser adaptation: exchange copies bytes with Uint8Array.
import * as S from './shape.mjs';
import {stringify} from './json.mjs';
import {contract,context,hash,Result,validateD,rows,key,equal,ext} from './core.mjs';
import {validateG} from './graph.mjs';
import {validateR} from './runtime.mjs';
export{stringify}from'./json.mjs';

const defaultProcessor={identity:'agsdl-experiment/modular-javascript-reader',version:'0.1.0-candidate-1'};

export function run(request,implementation={}){
  const reportContract=implementation.contract??contract,processor=implementation.processor??defaultProcessor,validateDocument=implementation.validateD??validateD,validateGraph=implementation.validateG??validateG,validateRuntime=implementation.validateR??validateR;
  if(!S.object(request)||!['operation','primary','annexes'].every(k=>Object.hasOwn(request,k))||Object.keys(request).some(k=>!['operation','primary','annexes','losses'].includes(k)))throw new TypeError('Invalid request fields');
  const{operation,primary,annexes={},losses}=request;if(!(primary instanceof Uint8Array)||!S.object(annexes)||Object.entries(annexes).some(([k,v])=>!k||!(v instanceof Uint8Array)))throw new TypeError('Expected primary bytes and an annex byte map');
  if(!['inspect','validateD','validateG','resolveG','validateR','exchange','lossyExchange'].includes(operation))throw new TypeError('Unknown operation');if(losses!==undefined&&operation!=='lossyExchange')throw new TypeError('losses is only allowed for lossyExchange');
  if(losses!==undefined&&(!Array.isArray(losses)||losses.some(x=>{if(!S.object(x)||!equal(Object.keys(x).sort(),['input','location','information','reason','permission'].sort())||x.permission!==null||['input','information','reason'].some(k=>typeof x[k]!=='string'||!x[k]))return true;const l=x.location;return!S.object(l)||Object.keys(l).length!==1||!(Object.hasOwn(l,'pointer')?typeof l.pointer==='string':Object.hasOwn(l,'byte')&&Number.isSafeInteger(l.byte)&&l.byte>=0);})))throw new TypeError('Invalid prospective Loss record');
  const ctx=context('primary',primary,annexes),contexts=[ctx],inventory={tree:ctx.tree,states:[],opaque:[]},report={contract:reportContract,processor:{...processor},operation,inputs:[{id:'primary',sha256:hash(primary)},...Object.keys(annexes).sort().map(id=>({id:`annex/${id}`,sha256:hash(annexes[id])}))],results:[],inventory,losses:[],outputs:[]},artifacts=Object.create(null);let interpreted=new Set();
  if(operation==='inspect'){const r=new Result('primary','inspect',null,['P-SYNTAX']);if(ctx.error)r.find('P-SYNTAX',ctx.error.byte,'Invalid UTF-8 JSON','fail',true);report.results.push(r.finish());}
  else if(operation==='exchange'||operation==='lossyExchange'){
    const r=new Result('primary','exchange',null,[operation==='exchange'?'E-PRESERVE':'E-LOSS']);if(operation==='lossyExchange'){r.find('E-LOSS','','Lossy exchange is refused');report.losses=losses?.length?losses:[{input:'primary',location:{pointer:''},information:'unspecified requested loss',reason:'This edition permits no lossy exchange',permission:null}];}
    else{if(S.valid(S.List(S.Dependency),ctx.tree?.dependencies)){const ids=new Set(),roots=new Set();for(const[i,d]of ctx.tree.dependencies.entries()){const supplied=Object.hasOwn(annexes,d.id),p=`/dependencies/${i}`;if(ids.has(d.id)||roots.has(key(d.rootKey))||new Set(d.requiredFor).size!==d.requiredFor.length||(d.status==='included')!==supplied)r.find('E-PRESERVE','','Dependency accounting refuses exchange');if(d.sha256!==null&&supplied&&hash(annexes[d.id])!==d.sha256)r.find('E-PRESERVE',p,'Hash mismatch');if(d.requiredFor.includes('exchange')){if(!supplied||d.status!=='included')r.find('E-PRESERVE','','Required bytes missing');if(d.sha256===null)r.find('E-PRESERVE','','Required integrity unknown','inconclusive');}ids.add(d.id);roots.add(key(d.rootKey));}for(const id of Object.keys(annexes))if(!ids.has(id))r.find('E-PRESERVE','','Undeclared annex');}if(r.finish().verdict==='pass'){artifacts.primary=new Uint8Array(primary);for(const id of Object.keys(annexes))artifacts[`annex/${id}`]=new Uint8Array(annexes[id]);report.outputs=report.inputs.map(x=>({...x}));}}report.results.push(r.finish());
  }else{report.results.push(validateDocument(ctx));if(operation==='validateR'){const x=validateRuntime(ctx,inventory);report.results.push(x.result);interpreted=x.interpreted;}if(['validateG','resolveG'].includes(operation)){const x=validateGraph(ctx,operation,inventory);contexts.push(...x.contexts);report.results.push(...x.results);interpreted=x.selected;}}
  for(const c of contexts)collect(c,operation,inventory,interpreted,c!==ctx);inventory.opaque=inventory.opaque.filter((s,i,a)=>!a.some((t,j)=>j!==i&&t.input===s.input&&t.start<=s.start&&t.end>=s.end&&(t.start<s.start||t.end>s.end)));inventory.opaque=[...new Map(inventory.opaque.map(s=>[`${s.input}:${s.pointer}`,s])).values()];inventory.states=[...new Map(inventory.states.map(s=>[JSON.stringify(s),s])).values()];return{report,artifacts};
}
function state(inv,ctx,p,s,detail=s){inv.states.push({input:ctx.id,pointer:p,state:s,detail});}
function collect(ctx,operation,inv,interpreted,annex=false){
  const d=ctx.tree,exchange=['inspect','exchange','lossyExchange'].includes(operation),slice=p=>{const span=ctx.spans.get(p);if(span)inv.opaque.push({input:ctx.id,pointer:p,...span});};if(exchange)state(inv,ctx,'/dependencies',ctx.error||!S.object(d)?'unchecked':!S.has(d,'dependencies')?'absent':S.valid(S.List(S.Dependency),d.dependencies)?'declared':'unchecked');if(ctx.error)return;if(!S.object(d)){slice('');return;}
  for(const k of['graphs','runtime']){const active=!annex&&((k==='graphs'&&['validateG','resolveG'].includes(operation))||(k==='runtime'&&operation==='validateR'));state(inv,ctx,`/${k}`,!S.has(d,k)?'absent':active?'declared':'unchecked');if(S.has(d,k)&&!active)slice(`/${k}`);}
  if(!exchange||S.valid(S.List(S.Dependency),d.dependencies))for(const x of rows(ctx,'dependencies',S.Dependency))if(x.ok&&x.v.sha256===null)state(inv,ctx,`${x.p}/sha256`,'unknown');if(exchange&&S.has(d,'dependencies')&&!S.valid(S.List(S.Dependency),d.dependencies))slice('/dependencies');for(const x of rows(ctx,'relations',S.Relation))if(x.ok&&ext(x.v.target))state(inv,ctx,`${x.p}/target`,'unchecked');for(const k of['annotations','evidence'])if(S.has(d,k))slice(`/${k}`);if(S.object(d.root))for(const k of['payload','annotations'])if(S.has(d.root,k))slice(`/root/${k}`);
  for(const[i,v]of(Array.isArray(d.definitions)?d.definitions:[]).entries())if(S.object(v))for(const k of['payload','annotations','provenance'])if(S.has(v,k)){const p=`/definitions/${i}/${k}`,seen=interpreted.has(p)||interpreted.has(`${ctx.id}:${p}`);if(k!=='payload'||!seen)slice(p);else if(operation==='validateR'){if(v.kind==='Instructions')slice(`${p}/body`);if(v.kind==='Skill'){slice(`${p}/preconditions`);slice(`${p}/completion`);}if(v.kind==='Tool'&&Array.isArray(v.payload?.failures))for(const[i,failure]of v.payload.failures.entries())if(typeof failure==='string')slice(`${p}/failures/${i}`);}}
  for(const[i,v]of(Array.isArray(d.extensions)?d.extensions:[]).entries())if(S.has(v,'payload'))slice(`/extensions/${i}/payload`);
  if(operation==='validateR'&&S.object(d.runtime)&&Array.isArray(d.runtime.configurations))for(const[ci,c]of d.runtime.configurations.entries())if(S.object(c)&&Array.isArray(c.agents))for(const[ai,a]of c.agents.entries())if(S.object(a)){const ap=`/runtime/configurations/${ci}/agents/${ai}`;if(S.has(a,'parameters'))slice(`${ap}/parameters`);for(const[ti,t]of(Array.isArray(a.tools)?a.tools:[]).entries())for(const[ii,x]of(Array.isArray(t?.choices)?t.choices:[]).entries())if(S.has(x,'parameters'))slice(`${ap}/tools/${ti}/choices/${ii}/parameters`);for(const[xi,x]of(Array.isArray(a.applications)?a.applications:[]).entries())if(S.has(x,'parameters'))slice(`${ap}/applications/${xi}/parameters`);}
}
